//! SQLite-backed audit ledger for ZKP proof records.
//!
//! Every proof generated by the CLI or MATLAB interface is logged here
//! for post-hoc auditability. The coordinator or any auditor can query
//! the ledger to verify that all proofs were generated and verified.
//!
//! Table schema:
//!   id         INTEGER PRIMARY KEY AUTOINCREMENT
//!   timestamp  TEXT    (ISO 8601 UTC, e.g. "2026-01-15T10:30:00Z")
//!   actor      TEXT    (e.g. "consumer_1", "provider_10")
//!   action     TEXT    (e.g. "commit_consumer", "prove_sufficiency")
//!   proof_json TEXT    (full JSON of the proof struct)

use rusqlite::{params, Connection};
use serde::{Deserialize, Serialize};

/// A single audit log entry.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct AuditEntry {
    pub id: i64,
    pub timestamp: String,
    pub actor: String,
    pub action: String,
    pub proof_json: String,
}

/// SQLite-backed audit ledger.
pub struct AuditLedger {
    conn: Connection,
}

impl AuditLedger {
    /// Open (or create) an audit ledger at the given path.
    ///
    /// Use `":memory:"` for an in-memory DB (useful for testing).
    pub fn new(path: &str) -> Result<Self, String> {
        let conn =
            Connection::open(path).map_err(|e| format!("Failed to open ledger DB: {}", e))?;

        conn.execute_batch(
            "CREATE TABLE IF NOT EXISTS audit_log (
                id         INTEGER PRIMARY KEY AUTOINCREMENT,
                timestamp  TEXT    NOT NULL,
                actor      TEXT    NOT NULL,
                action     TEXT    NOT NULL,
                proof_json TEXT    NOT NULL
            );",
        )
        .map_err(|e| format!("Failed to create table: {}", e))?;

        Ok(Self { conn })
    }

    /// Log a proof to the audit ledger.
    ///
    /// Returns the row ID of the inserted entry.
    pub fn log_proof(
        &self,
        actor: &str,
        action: &str,
        proof_json: &str,
    ) -> Result<i64, String> {
        // Use SQLite's datetime('now') for a consistent UTC timestamp
        self.conn
            .execute(
                "INSERT INTO audit_log (timestamp, actor, action, proof_json)
                 VALUES (datetime('now'), ?1, ?2, ?3)",
                params![actor, action, proof_json],
            )
            .map_err(|e| format!("Failed to insert: {}", e))?;

        Ok(self.conn.last_insert_rowid())
    }

    /// Retrieve all audit entries for a given actor.
    pub fn get_proofs_by_actor(&self, actor: &str) -> Result<Vec<AuditEntry>, String> {
        let mut stmt = self
            .conn
            .prepare(
                "SELECT id, timestamp, actor, action, proof_json
                 FROM audit_log WHERE actor = ?1 ORDER BY id",
            )
            .map_err(|e| format!("Failed to prepare query: {}", e))?;

        let entries = stmt
            .query_map(params![actor], |row| {
                Ok(AuditEntry {
                    id: row.get(0)?,
                    timestamp: row.get(1)?,
                    actor: row.get(2)?,
                    action: row.get(3)?,
                    proof_json: row.get(4)?,
                })
            })
            .map_err(|e| format!("Query failed: {}", e))?
            .collect::<Result<Vec<_>, _>>()
            .map_err(|e| format!("Row read failed: {}", e))?;

        Ok(entries)
    }

    /// Retrieve all audit entries.
    pub fn get_all_proofs(&self) -> Result<Vec<AuditEntry>, String> {
        let mut stmt = self
            .conn
            .prepare(
                "SELECT id, timestamp, actor, action, proof_json
                 FROM audit_log ORDER BY id",
            )
            .map_err(|e| format!("Failed to prepare query: {}", e))?;

        let entries = stmt
            .query_map([], |row| {
                Ok(AuditEntry {
                    id: row.get(0)?,
                    timestamp: row.get(1)?,
                    actor: row.get(2)?,
                    action: row.get(3)?,
                    proof_json: row.get(4)?,
                })
            })
            .map_err(|e| format!("Query failed: {}", e))?
            .collect::<Result<Vec<_>, _>>()
            .map_err(|e| format!("Row read failed: {}", e))?;

        Ok(entries)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_ledger_insert_and_retrieve() {
        let ledger = AuditLedger::new(":memory:").expect("open");
        let id = ledger
            .log_proof("consumer_1", "commit_consumer", r#"{"cid":1}"#)
            .expect("insert");
        assert!(id > 0, "row ID must be positive");

        let all = ledger.get_all_proofs().expect("get_all");
        assert_eq!(all.len(), 1);
        assert_eq!(all[0].actor, "consumer_1");
        assert_eq!(all[0].action, "commit_consumer");
        assert_eq!(all[0].proof_json, r#"{"cid":1}"#);
        assert!(!all[0].timestamp.is_empty(), "timestamp must be set");
    }

    #[test]
    fn test_ledger_by_actor() {
        let ledger = AuditLedger::new(":memory:").expect("open");
        ledger
            .log_proof("consumer_1", "commit", r#"{"a":1}"#)
            .expect("insert");
        ledger
            .log_proof("provider_10", "commit", r#"{"b":2}"#)
            .expect("insert");
        ledger
            .log_proof("consumer_1", "verify", r#"{"a":3}"#)
            .expect("insert");

        let c1 = ledger.get_proofs_by_actor("consumer_1").expect("query");
        assert_eq!(c1.len(), 2);
        assert_eq!(c1[0].action, "commit");
        assert_eq!(c1[1].action, "verify");

        let p10 = ledger.get_proofs_by_actor("provider_10").expect("query");
        assert_eq!(p10.len(), 1);
    }

    #[test]
    fn test_ledger_empty() {
        let ledger = AuditLedger::new(":memory:").expect("open");
        let all = ledger.get_all_proofs().expect("get_all");
        assert!(all.is_empty(), "new ledger must be empty");

        let by_actor = ledger
            .get_proofs_by_actor("nobody")
            .expect("by_actor");
        assert!(by_actor.is_empty(), "unknown actor must return empty");
    }

    #[test]
    fn test_ledger_multiple_actors() {
        let ledger = AuditLedger::new(":memory:").expect("open");
        for i in 0..5 {
            let actor = format!("vehicle_{}", i);
            ledger
                .log_proof(&actor, "commit", &format!(r#"{{"id":{}}}"#, i))
                .expect("insert");
        }
        let all = ledger.get_all_proofs().expect("get_all");
        assert_eq!(all.len(), 5);

        // Each actor has exactly 1 entry
        for i in 0..5 {
            let actor = format!("vehicle_{}", i);
            let entries = ledger.get_proofs_by_actor(&actor).expect("by_actor");
            assert_eq!(entries.len(), 1);
        }
    }
}
